function applyCoupon(total, percent) {
  const discount = (total * percent) / 100;
  return total - discount;
}

function checkoutTotal(items, couponPercent) {
  let total = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  if (couponPercent) {
    total = applyCoupon(total, couponPercent);
  }
  return applyCoupon(total, couponPercent || 0);
}

module.exports = { applyCoupon, checkoutTotal };

